// Comprehensive species data including biological and tracking information

export interface SpeciesData {
  id: string;
  name: string;
  scientificName: string;
  nickname: string;
  category: "spiral" | "plains" | "desert" | "small" | "dangerous";
  investment: string;
  
  // Physical Specifications
  biometrics: {
    weight: { male: string; female: string };
    height: { male: string; female: string } | string;
    hornLength?: string;
    hornSpan?: string;
    topSpeed?: string;
  };
  
  // Biological Information
  biology: {
    digestiveType: "ruminant" | "hindgut";
    feedingGuild: "browser" | "grazer" | "mixed" | "grazer/rooter";
    primaryForage: string;
    muzzleShape: string;
    dentalFormula?: string;
    waterDependence: string;
    habitat: string;
  };
  
  // Morphology & Anatomy
  morphology: {
    cranial: string;
    dentition: string;
    skeletal: string;
    dentalFormula?: string;
    hoof: {
      dimensions: string;
      shape: string;
      distinctive: string;
      substrate: string;
    };
    specialAdaptations: string[];
  };
  
  // Behavior & Ecology
  behavior: {
    social: string;
    feeding: string;
    defense: string;
    reproduction?: string;
    uniqueBehaviors: string[];
  };
  
  // Tracking Information
  tracking: {
    trackMorphology: string;
    trackDimensions: string;
    gaitSignature: string;
    behavioralSpoor: string;
    strategy: string;
    dangerLevel?: string;
    keySigns: string[];
  };
  
  // Hunting Information
  hunting: {
    caliber: string;
    shotPlacement: string;
    trophy: string;
    meat: string;
    difficulty: string;
  };
  
  // Description
  description: string;
  conservationNarrative?: string;
}

